import{f as a,c as t,o as e,a5 as o}from"./chunks/framework.BsEAYNxL.js";const d=JSON.parse('{"title":"AI 编年史 02：扩散模型 (Diffusion) 的造梦之旅","description":"","frontmatter":{"title":"AI 编年史 02：扩散模型 (Diffusion) 的造梦之旅","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Diffusion","GAN","ControlNet","Video Generation","Chronicle"],"ai_role":"writer","reading_stats":{"count":1899,"minutes":5}},"headers":[],"relativePath":"ai-chronicles/03-diffusion.md","filePath":"ai-chronicles/03-diffusion.md","lastUpdated":null}'),i={name:"ai-chronicles/03-diffusion.md"};function n(l,r,s,g,h,u){return e(),t("div",null,[...r[0]||(r[0]=[o('<h2 id="第一阶段-gan-的统治-——-黑暗中摸索-2014-2020" tabindex="-1">第一阶段：GAN 的统治 —— 黑暗中摸索 (2014 - 2020) <a class="header-anchor" href="#第一阶段-gan-的统治-——-黑暗中摸索-2014-2020" aria-label="Permalink to &quot;第一阶段：GAN 的统治 —— 黑暗中摸索 (2014 - 2020)&quot;">​</a></h2><p>在扩散模型出现之前，生成式 AI 的绝对王者是 <strong><a href="https://arxiv.org/abs/1406.2661" target="_blank" rel="noreferrer">GAN (Generative Adversarial Networks, 2014)</a></strong>。</p><h3 id="_1-1-背景与痛点" tabindex="-1">1.1 背景与痛点 <a class="header-anchor" href="#_1-1-背景与痛点" aria-label="Permalink to &quot;1.1 背景与痛点&quot;">​</a></h3><ul><li><strong>技术背景</strong>：Ian Goodfellow 在酒吧里灵光一闪提出的 GAN。 <ul><li><strong>Generator (G)</strong>：像伪钞制造者，负责画假图。</li><li><strong>Discriminator (D)</strong>：像警察，负责鉴别真假。</li><li>两者互相博弈，最后 G 画得连 D 都分不清。</li></ul></li><li><strong>核心痛点</strong>： <ul><li><strong>难以训练 (Mode Collapse)</strong>：G 容易偷懒，只画一种让 D 无法分辨的图（比如只画红头发），缺乏多样性。</li><li><strong>不稳定</strong>：两个网络像走钢丝，很容易不收敛。</li><li><strong>不可控</strong>：很难精准控制生成内容（比如“给这只猫戴上眼镜”）。</li></ul></li></ul><h3 id="_1-2-关键突破" tabindex="-1">1.2 关键突破 <a class="header-anchor" href="#_1-2-关键突破" aria-label="Permalink to &quot;1.2 关键突破&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/1511.06434" target="_blank" rel="noreferrer">DCGAN (2015)</a></strong>：首次引入 CNN，生成人脸。</li><li><strong><a href="https://arxiv.org/abs/1812.04948" target="_blank" rel="noreferrer">StyleGAN (2018)</a></strong>：NVIDIA 提出的高质量生成架构，通过 Style Transfer 控制生成细节，虽然画质惊艳，但仅限于人脸等特定领域。</li><li><strong><a href="https://arxiv.org/abs/1703.10593" target="_blank" rel="noreferrer">CycleGAN (2017)</a></strong>：实现了“马变斑马”的无监督转换。</li></ul><h2 id="第二阶段-扩散模型的诞生-——-物理学的启示-2020" tabindex="-1">第二阶段：扩散模型的诞生 —— 物理学的启示 (2020) <a class="header-anchor" href="#第二阶段-扩散模型的诞生-——-物理学的启示-2020" aria-label="Permalink to &quot;第二阶段：扩散模型的诞生 —— 物理学的启示 (2020)&quot;">​</a></h2><p>真正的变革来自物理学。<strong><a href="https://arxiv.org/abs/2006.11239" target="_blank" rel="noreferrer">DDPM</a></strong> 的提出，把“生成问题”变成了“去噪问题”。</p><h3 id="_2-1-背景与痛点" tabindex="-1">2.1 背景与痛点 <a class="header-anchor" href="#_2-1-背景与痛点" aria-label="Permalink to &quot;2.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：GAN 无法生成复杂场景（如一张图里既有猫又有狗还有桌子），且多样性差。</li><li><strong>核心痛点</strong>：需要一种更加数学完备、更加稳定的生成过程。</li></ul><h3 id="_2-2-关键论文" tabindex="-1">2.2 关键论文 <a class="header-anchor" href="#_2-2-关键论文" aria-label="Permalink to &quot;2.2 关键论文&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/2006.11239" target="_blank" rel="noreferrer">DDPM (Denoising Diffusion Probabilistic Models, 2020)</a></strong>：Jonathan Ho 等人提出。 <ul><li><strong>正向过程 (Forward)</strong>：像把一滴墨水滴入清水，慢慢把图片加上高斯噪声，直到变成纯噪声。</li><li><strong>反向过程 (Reverse)</strong>：训练一个神经网络 (UNet)，学会每一步怎么把噪声去掉一点点，就像把录像倒放。</li><li><strong>意义</strong>：证明了扩散模型能生成比 GAN 更多样化、更逼真的图像，且训练过程极其稳定（只需要预测噪声）。</li></ul></li></ul><h2 id="第三阶段-clip-的连接-——-文生图的曙光-2021" tabindex="-1">第三阶段：CLIP 的连接 —— 文生图的曙光 (2021) <a class="header-anchor" href="#第三阶段-clip-的连接-——-文生图的曙光-2021" aria-label="Permalink to &quot;第三阶段：CLIP 的连接 —— 文生图的曙光 (2021)&quot;">​</a></h2><p>有了生成能力还不够，还需要一种控制手段。OpenAI 发布的 <strong><a href="https://arxiv.org/abs/2103.00020" target="_blank" rel="noreferrer">CLIP</a></strong> 模型成为了连接文字与图像的桥梁。</p><h3 id="_3-1-背景与痛点" tabindex="-1">3.1 背景与痛点 <a class="header-anchor" href="#_3-1-背景与痛点" aria-label="Permalink to &quot;3.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：之前的模型只能“随机生成”，无法通过文字描述来画图（Text-to-Image）。</li><li><strong>核心痛点</strong>：计算机不知道“一只猫”这个词对应什么视觉特征。</li></ul><h3 id="_3-2-关键技术" tabindex="-1">3.2 关键技术 <a class="header-anchor" href="#_3-2-关键技术" aria-label="Permalink to &quot;3.2 关键技术&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/2103.00020" target="_blank" rel="noreferrer">CLIP (Contrastive Language-Image Pre-training)</a></strong>： <ul><li><strong>原理</strong>：利用互联网上 4 亿对 (图, 文) 数据进行训练，把图片和对应的文字映射到同一个向量空间。</li><li><strong>意义</strong>：当你说“宇航员骑马”时，CLIP 能告诉生成模型画出来的东西像不像“宇航员骑马”。</li></ul></li><li><strong>代表产品</strong>： <ul><li><strong><a href="https://arxiv.org/abs/2102.12092" target="_blank" rel="noreferrer">DALL-E 1 (OpenAI)</a></strong>：基于 Transformer + VQGAN，利用 CLIP 进行重排序。</li><li><strong><a href="https://github.com/alembics/disco-diffusion" target="_blank" rel="noreferrer">Disco Diffusion</a></strong>：早期开源社区的神作，利用 CLIP 指导扩散过程，虽然生成一张图要几十分钟，但艺术感极强。</li></ul></li></ul><h2 id="第四阶段-latent-diffusion-——-民主化的爆发-2022" tabindex="-1">第四阶段：Latent Diffusion —— 民主化的爆发 (2022) <a class="header-anchor" href="#第四阶段-latent-diffusion-——-民主化的爆发-2022" aria-label="Permalink to &quot;第四阶段：Latent Diffusion —— 民主化的爆发 (2022)&quot;">​</a></h2><p>直接在像素空间进行扩散计算量太大，普通显卡根本跑不动。<strong><a href="https://arxiv.org/abs/2112.10752" target="_blank" rel="noreferrer">Stable Diffusion</a></strong> 的出现改变了一切。</p><h3 id="_4-1-背景与痛点" tabindex="-1">4.1 背景与痛点 <a class="header-anchor" href="#_4-1-背景与痛点" aria-label="Permalink to &quot;4.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：Disco Diffusion 这种像素级扩散太慢，无法商业化。DALL-E 2 是闭源的。</li><li><strong>核心痛点</strong>：高分辨率图像 (512x512) 的像素点太多，计算成本指数级上升。</li></ul><h3 id="_4-2-解决方案-latent-diffusion-models-ldm" tabindex="-1">4.2 解决方案：Latent Diffusion Models (LDM) <a class="header-anchor" href="#_4-2-解决方案-latent-diffusion-models-ldm" aria-label="Permalink to &quot;4.2 解决方案：Latent Diffusion Models (LDM)&quot;">​</a></h3><p><strong>核心直觉：</strong> 如果直接在像素空间做扩散，成本会非常高：分辨率一上去，计算量和显存就爆炸。Latent Diffusion 的本质是<strong>先压缩，再生成</strong>。</p><ul><li><p><strong>Latent Space (潜在空间)</strong>：可以理解成一种“更小、更结构化的压缩表示”。</p></li><li><p><strong>类比（先把图片压成矢量草稿）</strong>：你不是在原图上擦擦改改，而是先把图压成“草稿”（Latent），在草稿层面修改，再导出成高清图。</p></li><li><p><strong>原理</strong>：</p><ol><li><strong>VAE (Variational Autoencoder)</strong>：先把图片压缩到一个低维的“潜空间 (Latent Space)”。比如把 512x512x3 的图压缩成 64x64x4 的 Latent。</li><li><strong>Diffusion</strong>：在潜空间里做加噪/去噪。计算量降低了几十倍。</li><li><strong>Decoding</strong>：最后把去噪后的 Latent 解码回高清图。</li></ol></li><li><p><strong>代表产品</strong>：</p><ul><li><strong><a href="https://github.com/CompVis/stable-diffusion" target="_blank" rel="noreferrer">Stable Diffusion 1.4 / 1.5</a></strong>：Stability AI 开源了权重，点燃了全球开发者的热情。这是 AI 绘画的“Linux 时刻”。</li><li><strong><a href="https://www.midjourney.com/" target="_blank" rel="noreferrer">Midjourney V4</a></strong>：闭源界的画质巅峰，审美调教极佳。</li></ul></li></ul><h3 id="_4-3-加速采样-ddim-2021" tabindex="-1">4.3 加速采样：DDIM (2021) <a class="header-anchor" href="#_4-3-加速采样-ddim-2021" aria-label="Permalink to &quot;4.3 加速采样：DDIM (2021)&quot;">​</a></h3><ul><li><strong>核心直觉</strong>：在不改变训练模型的情况下，选择一种更接近确定性的采样路径，从而减少采样步数。</li><li><strong>意义</strong>：传统的 DDPM 需要 1000 步才能生成一张图，DDIM 可以压缩到 50 步甚至更少。这也是为什么现在的 SD 只需要几秒钟就能出图。</li></ul><h2 id="第五阶段-可控生成与工业化-——-驯服野马-2023" tabindex="-1">第五阶段：可控生成与工业化 —— 驯服野马 (2023) <a class="header-anchor" href="#第五阶段-可控生成与工业化-——-驯服野马-2023" aria-label="Permalink to &quot;第五阶段：可控生成与工业化 —— 驯服野马 (2023)&quot;">​</a></h2><p>生成图虽然好看，但在工业界（游戏、设计）没法用，因为无法控制构图、姿势。</p><h3 id="_5-1-背景与痛点" tabindex="-1">5.1 背景与痛点 <a class="header-anchor" href="#_5-1-背景与痛点" aria-label="Permalink to &quot;5.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：设计师想画一个特定姿势的角色，或者给线稿上色。以前的 SD 只能抽卡（随机生成）。</li><li><strong>核心痛点</strong>：如何把结构信息 (Structure) 注入到生成过程中。</li></ul><h3 id="_5-2-关键技术" tabindex="-1">5.2 关键技术 <a class="header-anchor" href="#_5-2-关键技术" aria-label="Permalink to &quot;5.2 关键技术&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">ControlNet (2023)</a></strong>： <ul><li><strong>原理</strong>：给预训练好的 SD 模型加一个“旁路”网络，专门接收额外的控制条件（如边缘检测图、骨骼图、深度图）。</li><li><strong>意义</strong>：让 AI 绘画从“抽盲盒”变成了“精确作画”。指哪打哪。</li></ul></li><li><strong><a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">LoRA (Low-Rank Adaptation)</a></strong>： <ul><li><strong>原理</strong>：只训练模型中极小一部分参数，就能让模型学会特定的画风或角色。</li><li><strong>意义</strong>：每个人都可以用几十张图训练自己的专属模型。C站 (Civitai) 因此爆发。</li></ul></li></ul><h2 id="第六阶段-dit-与视频生成-——-动起来的世界-2024-future" tabindex="-1">第六阶段：DiT 与视频生成 —— 动起来的世界 (2024 - Future) <a class="header-anchor" href="#第六阶段-dit-与视频生成-——-动起来的世界-2024-future" aria-label="Permalink to &quot;第六阶段：DiT 与视频生成 —— 动起来的世界 (2024 - Future)&quot;">​</a></h2><p>当图像生成足够完美时，战场转移到了视频。</p><h3 id="_6-1-背景与痛点" tabindex="-1">6.1 背景与痛点 <a class="header-anchor" href="#_6-1-背景与痛点" aria-label="Permalink to &quot;6.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：生成视频不仅要每帧好看，还要帧与帧之间连贯（Temporal Consistency）。</li><li><strong>核心痛点</strong>：UNet 架构在处理长序列（视频帧）时，扩展性不如 Transformer。</li></ul><h3 id="_6-2-解决方案-diffusion-transformer-dit" tabindex="-1">6.2 解决方案：Diffusion Transformer (DiT) <a class="header-anchor" href="#_6-2-解决方案-diffusion-transformer-dit" aria-label="Permalink to &quot;6.2 解决方案：Diffusion Transformer (DiT)&quot;">​</a></h3><ul><li><p><strong>核心直觉</strong>：UNet 虽然好用，但它最初是为医疗图像分割设计的，且卷积结构在处理长距离依赖时不如 Transformer。DiT 就是把扩散模型里的“大脑”（去噪网络）从 UNet 换成了 Transformer。</p></li><li><p><strong>优势</strong>：</p><ul><li><strong>全局关系</strong>：Transformer 里的 Attention 机制能更好地处理画面中的长距离依赖（比如左边的树和右边的影子）。</li><li><strong>Scaling Law</strong>：Transformer 已经被 LLM 证明了具有极强的扩展性（Parameter Scaling）。</li></ul></li><li><p><strong>代表产品</strong>：</p><ul><li><strong><a href="https://openai.com/index/sora/" target="_blank" rel="noreferrer">Sora (OpenAI)</a></strong>：基于 DiT，能生成 60s 长视频，且物理规律大致正确。</li><li><strong><a href="https://stability.ai/news/stable-diffusion-3" target="_blank" rel="noreferrer">Stable Diffusion 3</a></strong>：全面转向 DiT 架构。</li><li><strong><a href="https://kling.kuaishou.com/" target="_blank" rel="noreferrer">Kling (快手可灵)</a> / Runway Gen-3</strong>：视频生成进入可用阶段。</li></ul></li></ul><h2 id="_7-工程坑点-你会在哪些地方翻车" tabindex="-1">7. 工程坑点：你会在哪些地方翻车 <a class="header-anchor" href="#_7-工程坑点-你会在哪些地方翻车" aria-label="Permalink to &quot;7. 工程坑点：你会在哪些地方翻车&quot;">​</a></h2><ol><li><strong>Prompt 失效</strong>：你以为模型在“理解”，其实它是在用统计关联补全你没说清的约束。</li><li><strong>参数打架</strong>：你以为步数越多越好，结果画面细节反而崩（采样器、CFG Scale、噪声调度在互相打架）。</li><li><strong>VAE 伪影</strong>：你以为 Latent 是免费午餐，结果遇到 VAE 解码带来的纹理怪异或细节损失（尤其是文字、人脸微表情）。</li></ol><h3 id="_7-1-总结" tabindex="-1">7.1 总结 <a class="header-anchor" href="#_7-1-总结" aria-label="Permalink to &quot;7.1 总结&quot;">​</a></h3><p>从 GAN 的对抗博弈，到 Diffusion 的物理去噪，再到 DiT 的架构统一。AI 绘画的发展史，就是人类试图用数学公式<strong>描述视觉世界</strong>的历史。</p>',43)])])}const c=a(i,[["render",n]]);export{d as __pageData,c as default};
